package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import com.openjiuwen.core.foundation.tool.ToolCard;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class WealthQueryTool extends Tool {
    private static final String OP_BALANCE = "get_account_balance";
    private static final String OP_PRODUCTS = "list_wealth_products";
    private static final String INPUT_ERROR = "TOOL_INPUT_CONTRACT_INVALID";
    private static final String RESPONSE_ERROR = "TOOL_RESPONSE_CONTRACT_INVALID";
    private static final String CARD_ERROR = "TOOL_CARD_CONTRACT_INVALID";

    private final Tool transport;

    public WealthQueryTool(Tool transport) {
        super(transport.getCard());
        this.transport = transport;
    }

    @Override
    protected Object invokeInternal(Map<String, Object> inputs, Map<String, Object> kwargs) throws Exception {
        ToolCard card = transport.getCard();
        if (card == null) {
            throw new IllegalArgumentException(CARD_ERROR);
        }
        String operation = card.getName();
        if (OP_BALANCE.equals(operation)) {
            Map<String, Object> balanceInput = validateBalanceInput(inputs);
            return validateBalanceResponse(transport.invoke(balanceInput, kwargs));
        }
        if (OP_PRODUCTS.equals(operation)) {
            Map<String, Object> productInput = validateProductInput(inputs);
            return validateProductsResponse(transport.invoke(productInput, kwargs));
        }
        throw new IllegalArgumentException(CARD_ERROR);
    }

    private static Map<String, Object> validateBalanceInput(Map<String, Object> inputs) {
        if (inputs == null || inputs.size() != 1 || !inputs.containsKey("accountId")) {
            throw new IllegalArgumentException(INPUT_ERROR);
        }
        Object accountId = inputs.get("accountId");
        if (!(accountId instanceof String) || ((String) accountId).isBlank()) {
            throw new IllegalArgumentException(INPUT_ERROR);
        }
        return inputs;
    }

    private static Map<String, Object> validateProductInput(Map<String, Object> inputs) {
        if (inputs == null || !inputs.isEmpty()) {
            throw new IllegalArgumentException(INPUT_ERROR);
        }
        return inputs;
    }

    private static Map<String, Object> validateBalanceResponse(Object response) {
        if (!(response instanceof Map)) {
            throw new IllegalArgumentException(RESPONSE_ERROR);
        }
        Map<?, ?> source = (Map<?, ?>) response;
        Object accountId = source.get("accountId");
        Object currency = source.get("currency");
        Object availableBalanceFen = source.get("availableBalanceFen");
        Object asOf = source.get("asOf");
        if (!(accountId instanceof String)
                || !(currency instanceof String)
                || !(availableBalanceFen instanceof Integer || availableBalanceFen instanceof Long)
                || !(asOf instanceof String)) {
            throw new IllegalArgumentException(RESPONSE_ERROR);
        }
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("accountId", accountId);
        result.put("currency", currency);
        result.put("availableBalanceFen", availableBalanceFen);
        result.put("asOf", asOf);
        return result;
    }

    private static Map<String, Object> validateProductsResponse(Object response) {
        if (!(response instanceof Map)) {
            throw new IllegalArgumentException(RESPONSE_ERROR);
        }
        Map<?, ?> source = (Map<?, ?>) response;
        Object rawItems = source.get("items");
        Object version = source.get("version");
        if (!(rawItems instanceof List) || !(version instanceof String)) {
            throw new IllegalArgumentException(RESPONSE_ERROR);
        }
        List<?> items = (List<?>) rawItems;
        List<Object> returnedItems = new ArrayList<>(items.size());
        for (Object rawItem : items) {
            if (!(rawItem instanceof Map)) {
                throw new IllegalArgumentException(RESPONSE_ERROR);
            }
            Map<?, ?> item = (Map<?, ?>) rawItem;
            Object productId = item.get("productId");
            Object name = item.get("name");
            Object status = item.get("status");
            Object minimumAmountFen = item.get("minimumAmountFen");
            Object description = item.get("description");
            if (!(productId instanceof String)
                    || !(name instanceof String)
                    || !(status instanceof String)
                    || !(minimumAmountFen instanceof Integer || minimumAmountFen instanceof Long)
                    || !(description instanceof String)) {
                throw new IllegalArgumentException(RESPONSE_ERROR);
            }
            Map<String, Object> returnedItem = new LinkedHashMap<>();
            returnedItem.put("productId", productId);
            returnedItem.put("name", name);
            returnedItem.put("status", status);
            returnedItem.put("minimumAmountFen", minimumAmountFen);
            returnedItem.put("description", description);
            returnedItems.add(returnedItem);
        }
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("items", returnedItems);
        result.put("version", version);
        return result;
    }
}
